∀ {n : ℕ} {H : ℕ → BfgsVerification.Mat n} {g : ℕ → BfgsVerification.Vec n} {α : ℕ → ℝ}
  {positive_definite : ∀ (k : ℕ), Matrix.PosDef (H k)} {alpha_pos : ∀ (k : ℕ), 0 < α k}
  {energy_pos : ∀ (k : ℕ), 0 < BfgsVerification.metricEnergy (H k) (g k)}
  {curvature_pos : ∀ (k : ℕ), 0 < BfgsVerification.dot (g (k + 1) - g k) (BfgsVerification.bfgsStep (H k) (g k) (α k))}
  {update :
    ∀ (k : ℕ),
      H (k + 1) = BfgsVerification.inverseBFGS (H k) (BfgsVerification.bfgsStep (H k) (g k) (α k)) (g (k + 1) - g k)}
  {H_1 : ℕ → BfgsVerification.Mat n} {g_1 : ℕ → BfgsVerification.Vec n} {α_1 : ℕ → ℝ}
  {positive_definite_1 : ∀ (k : ℕ), Matrix.PosDef (H_1 k)} {alpha_pos_1 : ∀ (k : ℕ), 0 < α_1 k}
  {energy_pos_1 : ∀ (k : ℕ), 0 < BfgsVerification.metricEnergy (H_1 k) (g_1 k)}
  {curvature_pos_1 :
    ∀ (k : ℕ), 0 < BfgsVerification.dot (g_1 (k + 1) - g_1 k) (BfgsVerification.bfgsStep (H_1 k) (g_1 k) (α_1 k))}
  {update_1 :
    ∀ (k : ℕ),
      H_1 (k + 1) =
        BfgsVerification.inverseBFGS (H_1 k) (BfgsVerification.bfgsStep (H_1 k) (g_1 k) (α_1 k)) (g_1 (k + 1) - g_1 k)},
  { H := H, g := g, α := α, positive_definite := positive_definite, alpha_pos := alpha_pos, energy_pos := energy_pos,
        curvature_pos := curvature_pos, update := update } =
      { H := H_1, g := g_1, α := α_1, positive_definite := positive_definite_1, alpha_pos := alpha_pos_1,
        energy_pos := energy_pos_1, curvature_pos := curvature_pos_1, update := update_1 } →
    H = H_1 ∧ g = g_1 ∧ α = α_1

∀ {n : ℕ} {F : BfgsVerification.Vec n → ℝ} {convex : ConvexOn ℝ Set.univ F} {x : ℕ → BfgsVerification.Vec n}
  {H : ℕ → BfgsVerification.Mat n} {g : ℕ → BfgsVerification.Vec n} {α : ℕ → ℝ} {c₁ c₂ : ℝ} {c₁_pos : 0 < c₁}
  {c₁_lt_c₂ : c₁ < c₂} {c₂_lt_one : c₂ < 1} {initial_posDef : Matrix.PosDef (H 0)} {alpha_pos : ∀ (k : ℕ), 0 < α k}
  {gradient_nonzero : ∀ (k : ℕ), g k ≠ 0}
  {hasGradient : ∀ (k : ℕ), HasFDerivAt F (BfgsVerification.gradientFunctional (g k)) (x k)}
  {step : ∀ (k : ℕ), x (k + 1) = x k + BfgsVerification.bfgsStep (H k) (g k) (α k)}
  {update :
    ∀ (k : ℕ),
      H (k + 1) = BfgsVerification.inverseBFGS (H k) (BfgsVerification.bfgsStep (H k) (g k) (α k)) (g (k + 1) - g k)}
  {armijo :
    ∀ (k : ℕ), F (x (k + 1)) ≤ F (x k) + c₁ * BfgsVerification.dot (g k) (BfgsVerification.bfgsStep (H k) (g k) (α k))}
  {weak_wolfe :
    ∀ (k : ℕ),
      c₂ * BfgsVerification.dot (g k) (BfgsVerification.bfgsStep (H k) (g k) (α k)) ≤
        BfgsVerification.dot (g (k + 1)) (BfgsVerification.bfgsStep (H k) (g k) (α k))}
  {convex_1 : ConvexOn ℝ Set.univ F} {x_1 : ℕ → BfgsVerification.Vec n} {H_1 : ℕ → BfgsVerification.Mat n}
  {g_1 : ℕ → BfgsVerification.Vec n} {α_1 : ℕ → ℝ} {c₁_1 c₂_1 : ℝ} {c₁_pos_1 : 0 < c₁_1} {c₁_lt_c₂_1 : c₁_1 < c₂_1}
  {c₂_lt_one_1 : c₂_1 < 1} {initial_posDef_1 : Matrix.PosDef (H_1 0)} {alpha_pos_1 : ∀ (k : ℕ), 0 < α_1 k}
  {gradient_nonzero_1 : ∀ (k : ℕ), g_1 k ≠ 0}
  {hasGradient_1 : ∀ (k : ℕ), HasFDerivAt F (BfgsVerification.gradientFunctional (g_1 k)) (x_1 k)}
  {step_1 : ∀ (k : ℕ), x_1 (k + 1) = x_1 k + BfgsVerification.bfgsStep (H_1 k) (g_1 k) (α_1 k)}
  {update_1 :
    ∀ (k : ℕ),
      H_1 (k + 1) =
        BfgsVerification.inverseBFGS (H_1 k) (BfgsVerification.bfgsStep (H_1 k) (g_1 k) (α_1 k)) (g_1 (k + 1) - g_1 k)}
  {armijo_1 :
    ∀ (k : ℕ),
      F (x_1 (k + 1)) ≤
        F (x_1 k) + c₁_1 * BfgsVerification.dot (g_1 k) (BfgsVerification.bfgsStep (H_1 k) (g_1 k) (α_1 k))}
  {weak_wolfe_1 :
    ∀ (k : ℕ),
      c₂_1 * BfgsVerification.dot (g_1 k) (BfgsVerification.bfgsStep (H_1 k) (g_1 k) (α_1 k)) ≤
        BfgsVerification.dot (g_1 (k + 1)) (BfgsVerification.bfgsStep (H_1 k) (g_1 k) (α_1 k))},
  { convex := convex, x := x, H := H, g := g, α := α, c₁ := c₁, c₂ := c₂, c₁_pos := c₁_pos, c₁_lt_c₂ := c₁_lt_c₂,
        c₂_lt_one := c₂_lt_one, initial_posDef := initial_posDef, alpha_pos := alpha_pos,
        gradient_nonzero := gradient_nonzero, hasGradient := hasGradient, step := step, update := update,
        armijo := armijo, weak_wolfe := weak_wolfe } =
      { convex := convex_1, x := x_1, H := H_1, g := g_1, α := α_1, c₁ := c₁_1, c₂ := c₂_1, c₁_pos := c₁_pos_1,
        c₁_lt_c₂ := c₁_lt_c₂_1, c₂_lt_one := c₂_lt_one_1, initial_posDef := initial_posDef_1, alpha_pos := alpha_pos_1,
        gradient_nonzero := gradient_nonzero_1, hasGradient := hasGradient_1, step := step_1, update := update_1,
        armijo := armijo_1, weak_wolfe := weak_wolfe_1 } →
    x = x_1 ∧ H = H_1 ∧ g = g_1 ∧ α = α_1 ∧ c₁ = c₁_1 ∧ c₂ = c₂_1

∀ {n : ℕ} (H : BfgsVerification.Mat n) (g y : BfgsVerification.Vec n) (α : ℝ),
  α ≠ 0 →
    BfgsVerification.metricEnergy H g ≠ 0 →
      -BfgsVerification.dot y (Matrix.mulVec H g) / BfgsVerification.metricEnergy H g ≠ 0 →
        let q := BfgsVerification.metricEnergy H g;
        let β := -BfgsVerification.dot y (Matrix.mulVec H g) / q;
        let v := Matrix.mulVec H g;
        BfgsVerification.inverseBFGS H (BfgsVerification.bfgsStep H g α) y =
          (1 + (β * q)⁻¹ • BfgsVerification.outer v y) * H * (1 + (β * q)⁻¹ • BfgsVerification.outer y v) +
            (α / (β * q)) • BfgsVerification.outer v v
